(()=>{const stage=document.querySelector('#stage');if(!stage)return;const save=()=>window.APANAM_PROJECT?.save?.();function add(title,sub){const e=document.createElement('div');e.className='element';e.dataset.type='bundle';e.innerHTML=`<b style="font-size:17px">${title}</b><small style="display:block;margin-top:3px">${sub}</small>`;Object.assign(e.style,{position:'absolute',left:'180px',top:(220+stage.querySelectorAll('.element').length*15)+'px',fontFamily:'Arial,sans-serif',padding:'11px 14px',borderRadius:'12px',background:'#fff',border:'1px solid #d1d5db',boxShadow:'0 4px 14px rgba(0,0,0,.1)',zIndex:'61'});stage.appendChild(e);save()}const ask=(title,q,d)=>{const v=prompt(q,d);if(v!==null&&v.trim())add(title,v.trim())};const tools={pack:()=>ask('Pack of','Quantity','2'),combo:()=>ask('Combo Offer','Products included','Bottle + Lunch Box'),buyget:()=>ask('Buy & Get','Offer','Buy 2 Get 1'),set:()=>ask('Complete Set','Set details','4 Piece Set'),saving:()=>ask('Bundle Saving','Saving','Save ₹150'),value:()=>ask('Value Pack','Value pack','Family Value Pack'),gift:()=>ask('Gift Included','Free gift','Free Cleaning Brush'),assorted:()=>ask('Assorted Pack','Variants','3 Assorted Colors'),multipack:()=>ask('Multi-Pack','Pack details','Pack of 6'),custom:()=>{const t=prompt('Bundle title','Special Bundle');if(t)ask(t,'Bundle details','Enter details')}};const items=[['pack','Pack of X'],['combo','Combo Offer'],['buyget','Buy X Get Y'],['set','Complete Set'],['saving','Bundle Saving'],['value','Value Pack'],['gift','Free Gift'],['assorted','Assorted Pack'],['multipack','Multi-Pack'],['custom','Custom Bundle']];let r=document.querySelector('aside.right');if(!r)return;let b=document.createElement('div');b.innerHTML='<h3>10 Product Bundle & Combo Tools</h3><p class="small">Combo, multipack और bundle listings के लिए साफ offer cards बनाएँ।</p>'+items.map((x,i)=>`<button id="epb${i}">${x[1]}</button>`).join('');r.insertBefore(b,r.firstChild);items.forEach((x,i)=>document.querySelector('#epb'+i).onclick=tools[x[0]]);window.APANAM_BUNDLE_TOOLS=tools})();